use_Name, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Mode, CASE WHEN COD = \'0\' THEN \'Prepaid\' ELSE \'COD\' END AS Payment_Method, \"shipping courier\" AS Courier, \"shipping courier status\" AS shipping_status, \"shipping tracking status\" as shipping_tracking_status, 1 AS shippedQuantity, TO_CHAR(TO_TIMESTAMP(NULLIF(\"packing time\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS packing_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"dispatch date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS dispatch_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"ewaybill date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS ewaybill_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"delivery time\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS delivery_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"return date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS return_date, TO_CHAR(TO_TIMESTAMP(NULLIF(\"reverse pickup created date\", \'\'), \'YYYY-MM-DD HH24:MI:SS\'), \'YYYY-MM-DD\"T\"HH24:MI:SS\') AS reverse_pickup_date, \"reverse pickup code\" as reverse_pickup_code, \"return remarks\" as return_remarks, \"reverse pickup reason\" as reverse_pickup_reason, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS varchar))) <> \'null\' THEN 1 ELSE 0 END AS return_flag, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS varchar))) <> \'null\' THEN 1 ELSE 0 END AS return_quantity, CASE WHEN \"return date\" IS NOT NULL AND TRIM(CAST(\"return date\" AS varchar)) <> \'\' AND LOWER(TRIM(CAST(\"return date\" AS varchar))) <> \'null\' THEN CAST(\"selling price\" AS double precision) ELSE 0 END AS return_sales, CASE WHEN lower(\"sale order status\") LIKE \'%cancel%\' OR lower(\"shipping courier status\") LIKE \'%cancel%\' THEN 1 ELSE 0 END AS cancell